effect.shader:
vec3 u_xlat0;
mediump vec2 u_xlat16_1;
vec3 u_xlat2;
float u_xlat3;
void main()
{
    u_xlat0.xy = texture(inputImg, vs_TEXCOORD1.xy).xy;
    u_xlat16_1.xy = u_xlat0.xy * vec2(2.0, 2.0) + vec2(-1.0, -1.0);
    u_xlat0.xy = u_xlat16_1.xy * vec2(_BumpAmt);
    u_xlat0.xy = u_xlat0.xy * vs_COLOR0.xx;
    u_xlat0.xy = u_xlat0.xy * acScreenNorm.ww + acScreenNorm.xy;
    u_xlat0.xy = u_xlat0.xy / acScreenNorm.ww;
    u_xlat0.xyz = texture(env_tex, u_xlat0.xy).xyz;
    u_xlat2.xyz = texture(MainTex, vs_TEXCOORD2.xy).xyz;
    u_xlat2.xyz = u_xlat2.xyz * vs_COLOR0.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vec3(vec3(_ColorStrength, _ColorStrength, _ColorStrength));
    fragColor.xyz = u_xlat2.xyz * _TintColor.xyz + u_xlat0.xyz;
    u_xlat0.x = texture(CutOut, vs_TEXCOORD3.xy).w;
    u_xlat0.x = u_xlat0.x * vs_COLOR0.w;
    u_xlat3 = vs_COLOR0.w * _TintColor.w;
    fragColor.w = u_xlat0.x * u_xlat3;
    return;
}
